            tool["project_adapter_available"] = True
            tool["canonical_adapter_available"] = False
            tool["runtime_admission_available"] = True
            tool["development_adapter_cli"] = "favor-annotate"
            tool["runtime_preparation_cli"] = "python3 tools/literature/prepare_favor_runtime.py"
            tool["development_candidate"] = "build/literature-review/favor-runtime/annotator-root-candidate-2/omicsmatic-0.3.7.jar"
            tool["development_candidate_sha256"] = proof["candidate_sha256"]
            tool["workflow_validation"] = "favor-validation.json"
            tool["source_role_coverage"] = "favor-role-coverage.json"
            tool["source_roles_reviewed"] = 1
